import * as PAGES from 'constants/pages';
import React, { useEffect } from 'react';
import BusyIndicator from 'component/common/busy-indicator';
import RewardListClaimed from 'component/rewardListClaimed';
import RewardTile from 'component/rewardTile';
import Button from 'component/button';
import Page from 'component/page';
import classnames from 'classnames';
import REWARD_TYPES from 'rewards';
import RewardAuthIntro from 'component/rewardAuthIntro';
import Card from 'component/common/card';
import I18nMessage from 'component/i18nMessage';
import { SITE_HELP_EMAIL, SITE_NAME } from 'config';
import { useAppSelector, useAppDispatch } from 'redux/hooks';
import { selectUser } from 'redux/selectors/user';
import { selectFetchingRewards, selectUnclaimedRewards, selectClaimedRewards } from 'redux/selectors/rewards';
import { doUserFetch } from 'redux/actions/user';
import { doRewardList } from 'redux/actions/rewards';
import { selectDaemonSettings } from 'redux/selectors/settings';

function RewardsPage() {
  const dispatch = useAppDispatch();
  const daemonSettings = useAppSelector(selectDaemonSettings);
  const fetching = useAppSelector(selectFetchingRewards);
  const rewards = useAppSelector(selectUnclaimedRewards);
  const claimed = useAppSelector(selectClaimedRewards);
  const user = useAppSelector(selectUser);

  useEffect(() => {
    const rewardsApproved = user && user.is_reward_approved;
    dispatch(doRewardList());
    if (!rewardsApproved) {
      dispatch(doUserFetch());
    }
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  function renderPageHeader() {
    const rewardsEnabled = IS_WEB || (daemonSettings && daemonSettings.share_usage_data);

    if (user && !user.is_reward_approved && rewardsEnabled) {
      if (!user.primary_email || !user.has_verified_email || !user.is_identity_verified) {
        return (
          <div className="section">
            <RewardAuthIntro />
          </div>
        );
      }

      return (
        <Card
          className="section"
          title={__('Receive Credits validation pending')}
          body={
            <React.Fragment>
              <p>
                {__(
                  'This account must undergo review before you can participate in the credits program. Not all users and regions may qualify.'
                )}{' '}
                {__('This can take anywhere from a few hours to several days. Please be patient.')}
              </p>

              <p>
                {__(
                  'We apologize for this inconvenience, but have added this additional step to prevent abuse. Users on VPN or shared connections will continue to see this message and are not eligible for Credits.'
                )}
              </p>
              <p>
                <I18nMessage
                  tokens={{
                    help_email: SITE_HELP_EMAIL,
                    site_name: SITE_NAME,
                  }}
                >
                  Send us an email to %help_email% if you continue to see this message. You can continue to use
                  %site_name% without this feature.
                </I18nMessage>
                {__('Enjoy all the awesome free content in the meantime!')}
              </p>
            </React.Fragment>
          }
          actions={
            <div className="section__actions">
              <Button navigate="/" button="primary" label="Return Home" />
              <Button onClick={() => dispatch(doUserFetch())} button="link" label="Refresh" />
            </div>
          }
        />
      );
    }

    return null;
  }

  function renderCustomRewardCode() {
    const isNotEligible = !user || !user.primary_email || !user.has_verified_email || !user.is_reward_approved;
    return (
      <RewardTile
        key={(REWARD_TYPES as any).TYPE_GENERATED_CODE}
        reward={
          {
            reward_type: (REWARD_TYPES as any).TYPE_GENERATED_CODE,
            reward_title: __('Custom Code'),
            reward_description: __(
              'Are you a supermodel or rockstar that received a custom Credits code? Claim it here.'
            ),
          } as any
        }
        disabled={isNotEligible}
      />
    );
  }

  function renderUnclaimedRewards() {
    if (!IS_WEB && daemonSettings && !daemonSettings.share_usage_data) {
      return (
        <section className="card card--section">
          <h2 className="card__title card__title--deprecated">{__('Credits Disabled')}</h2>
          <p className="error__text">
            <I18nMessage
              tokens={{
                settings: <Button button="link" navigate="/$/settings" label="Settings" />,
              }}
            >
              Receiving credits feature is currently disabled for your account. Turn on diagnostic data sharing, in
              %settings%, to re-enable them.
            </I18nMessage>
          </p>
        </section>
      );
    } else if (fetching) {
      return <BusyIndicator message={__('Fetching available credits')} />;
    } else if (user === null) {
      return (
        <p className="help">{__('This application is unable to receive credits due to an authentication failure.')}</p>
      );
    } else if (!rewards || rewards.length <= 0) {
      return (
        <Card
          title={__('No credits available')}
          subtitle={
            claimed && claimed.length
              ? __(
                  "You have claimed all available credits! We're regularly adding more so be sure to check back later."
                )
              : __('There are no credits available at this time, please check back later.')
          }
          actions={<Button button="primary" navigate={`/$/${PAGES.DISCOVER}`} label={__('Go Home')} />}
        />
      );
    }

    const isNotEligible = !user || !user.primary_email || !user.has_verified_email || !user.is_reward_approved;
    return (
      <div
        aria-hidden={isNotEligible}
        className={classnames('card__list', {
          'card--disabled': isNotEligible,
        })}
      >
        {rewards.map((reward) => (
          <RewardTile disabled={isNotEligible} key={reward.claim_code} reward={reward} />
        ))}
        {renderCustomRewardCode()}
      </div>
    );
  }

  return (
    <Page>
      {renderPageHeader()}
      <div className="section">{renderUnclaimedRewards()}</div>
      <RewardListClaimed />
    </Page>
  );
}

export default RewardsPage;
